import{c as a,Q as i,j as n,m as r}from"./chunks/framework.BXc4yaFE.js";const f=JSON.parse('{"title":"More Than Can Be Said: A Benchmark and Framework for Pre-Question Scientific Ideation","description":"","frontmatter":{"url":"https://arxiv.org/abs/2605.06345","title":"More Than Can Be Said: A Benchmark and Framework for Pre-Question Scientific Ideation","archived_date":"2026-07-27T00:00:00.000Z","arxiv_id":2605.06345,"authors":["Jie Yu","Song Qiu"],"domain":"hypothesis-generation-infrastructure","published_date":"2026-05-07T00:00:00.000Z","source_routine":"routine-e"},"headers":[],"relativePath":"research/papers/2026-07-27-pre-question-scientific-ideation-2605-06345.md","filePath":"research/papers/2026-07-27-pre-question-scientific-ideation-2605-06345.md","lastUpdated":1785909234000}'),t={name:"research/papers/2026-07-27-pre-question-scientific-ideation-2605-06345.md"};function o(s,e,c,d,h,p){return i(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="more-than-can-be-said-a-benchmark-and-framework-for-pre-question-scientific-ideation" tabindex="-1">More Than Can Be Said: A Benchmark and Framework for Pre-Question Scientific Ideation <a class="header-anchor" href="#more-than-can-be-said-a-benchmark-and-framework-for-pre-question-scientific-ideation" aria-label="Permalink to &quot;More Than Can Be Said: A Benchmark and Framework for Pre-Question Scientific Ideation&quot;">​</a></h1><h2 id="摘要-核心貢獻" tabindex="-1">摘要 / 核心貢獻 <a class="header-anchor" href="#摘要-核心貢獻" aria-label="Permalink to &quot;摘要 / 核心貢獻&quot;">​</a></h2><p>提出 InciteResearch 多 agent 框架，處理研究者在能明確表述問題前的「內隱摩擦」（tacit friction）——一種尚無法言明的錯位直覺。三階段：①以五維研究者側寫錨定具體摩擦點 ②挑戰隱藏假設（優化 feasibility×novelty 乘積 + 七階段因果推導鏈）③驗證方法是否為重新框架後洞見的必然結果。並提出 TF-Bench 評測基準，涵蓋四種科學模式、區分領域相關/不相關的靈感來源。相較 prompt-based baseline，novelty 分數由 3.671 升至 4.250，impact 由 3.806 升至 4.397，且產出從「單純重組」轉向「更深的架構性洞見」。</p><h2 id="為何屬「新領域」" tabindex="-1">為何屬「新領域」 <a class="header-anchor" href="#為何屬「新領域」" aria-label="Permalink to &quot;為何屬「新領域」&quot;">​</a></h2><p>「問題形成前的內隱摩擦處理」與 workspace 既有覆蓋無語意重疊；核心關鍵詞 hypothesis 於既有覆蓋集合反向 grep 命中為 0，且概念上與 know-your-unknowns SKILL 的 Unknown Knowns 象限相近但非既有收錄領域。</p>',5)])])}const m=a(t,[["render",o]]);export{f as __pageData,m as default};
